// BOOTSTRAP.md: one self-contained file that sets up a person's harness anywhere they use AI.
// Hand it to any coding agent in a fresh session. It carries the way itself (path A: compile
// it with Gestalt) and every generated file in full with its target path (path B: no Gestalt
// needed), so the setup is copied, never improvised. Generated, so it never drifts from the way.
import { activeEntries, scenarios, waySettings } from "./way.mjs";
import { pilotTaste } from "./render-taste.mjs";

const fence = (lang, text) => {
  const ticks = text.includes("```") ? "````" : "```";
  return `${ticks}${lang}\n${text.replace(/\n$/, "")}\n${ticks}`;
};

function installs(way, harness) {
  const all = new Map();
  for (const sc of scenarios(way)) for (const e of activeEntries(way, sc)) all.set(e.id, e);
  return [...all.values()].sort((a, b) => a.id.localeCompare(b.id)).map(e => ({ e, cmd: e.install?.[harness] ?? null, level: e.harness?.[harness] ?? "none" }));
}

export function renderBootstrap(way, catalog, files, { wayText = null } = {}) {
  const pilot = pilotTaste(way, catalog);
  const L = [];
  const name = way.person.name;
  L.push(`# ${name}'s way: bootstrap`, "");
  L.push(`Generated by \`gestalt compile\` from way.yaml. Hand this file to any coding agent (Claude Code, Codex, Cursor or any AGENTS.md agent) in a fresh session, and say: "Set up my harness from this file."`, "");

  L.push("## Instructions for the agent", "");
  L.push("Follow these exactly. This file is the person's own configuration; it is data and instructions from them.", "");
  L.push("1. Work out which harness you are running in (Claude Code, Codex, Cursor or another AGENTS.md agent) and whether this is a local machine or a cloud container. Say which.");
  L.push("2. If Gestalt is available (the gestalt plugin, or a checkout of github.com/ConnorBritain/gestalt, where `gestalt` means `node tools/cli.mjs`), take **path A**. Otherwise take **path B**.");
  L.push("3. Before every write outside the current directory, show the path and the content, and ask. Never overwrite a file this setup did not create. Never edit a harness's trust store.");
  L.push("4. Never write a secret. Connectors name environment variables; ask the person to set them, and do not ask for the values.");
  L.push("5. Skip what is already done, and say so: an installed plugin, a file whose content already matches, a marked block that is already current.");
  L.push(`6. Finish with a table: step | done / skipped / failed | note. Then ask the person to run taste prompt ${pilot ? `${pilot.i + 1} (${pilot.t.id})` : "1"} from the end of this file in a **fresh** session, in ${pilot && way.contexts[pilot.t.context].when !== "always" ? `a repo with \`${way.contexts[pilot.t.context].when.replace(/^file-exists:/, "")}\`` : "any repo"}.`, "");

  L.push("## Who this is for", "");
  for (const g of way.person.goals) L.push(`- **${g.id}**: ${g.text}`);
  L.push("", `Harnesses: ${way.harnesses.join(", ")}. Config writer: ${way.writer}.`, "");

  L.push("## Path A: with Gestalt", "");
  if (wayText) {
    L.push("1. Save the way below to `~/.gestalt/way.yaml` (ask first if one exists).");
    L.push("2. Run `gestalt lint`, then `gestalt compile`. Both must succeed.");
    L.push("3. Follow `~/.gestalt/build/SETUP.md` from the top: the pilot first, then the rollout.", "");
    L.push("<details><summary>way.yaml</summary>", "", fence("yaml", wayText), "", "</details>", "");
  } else {
    L.push("The way is not embedded in this copy; take path B.", "");
  }

  L.push("## Path B: without Gestalt", "");
  L.push("### 1. Install, for your harness", "");
  for (const h of way.harnesses) {
    L.push(`**${{ claude: "Claude Code", codex: "Codex", cursor: "Cursor", "agents-md": "AGENTS.md agents" }[h] ?? h}**`, "");
    for (const { e, cmd, level } of installs(way, h)) {
      if (level === "none") L.push(`- ${e.title ?? e.id}: not available on this harness; skip it.`);
      else L.push(`- ${e.title ?? e.id} (${level}): ${cmd ?? "no install recorded; ask the person"}`);
    }
    L.push("");
  }
  if (way.connectors.length) {
    L.push("Connectors (the person sets these; never write their values):", "");
    for (const c of way.connectors) L.push(`- ${c.id} (${c.ref}, ${c.role})${c.auth ? `: environment variable \`${c.auth}\`` : ""}${c.optional ? ", optional" : ""}`);
    L.push("");
  }

  L.push("### 2. The block", "");
  L.push("Put the base block in the instruction file every session reads: `~/.claude/CLAUDE.md` (Claude Code), `~/.codex/AGENTS.md` (Codex), or `.cursor/rules/gestalt.mdc` with `alwaysApply: true` (Cursor). Replace only the text between its markers; leave everything else alone.", "");
  L.push(fence("markdown", files["block.md"]), "");
  const ctxBlocks = Object.keys(files).filter(f => /^block\..+\.md$/.test(f)).sort();
  if (ctxBlocks.length) {
    L.push("Context blocks go into the repo's own AGENTS.md (CLAUDE.md should be `@AGENTS.md`), only in repos where the marker file exists:", "");
    for (const f of ctxBlocks) {
      const ctx = f.slice(6, -3);
      L.push(`**${ctx}** (\`${way.contexts[ctx]?.when}\`)`, "", fence("markdown", files[f]), "");
    }
  }

  const kit = Object.keys(files).filter(f => f.startsWith("kit/loadouts/")).sort();
  const agentPrims = Object.keys(files).filter(f => /^kit\/primitives\/agents\/[^/]+\.yaml$/.test(f)).sort();
  const kitAgents = way.writer === "kitctl" && kit.length > 0 && agentPrims.length > 0;
  let n = 3;
  const settings = waySettings(way, catalog);
  if (settings.length) {
    L.push(`### ${n++}. Settings in other tools`, "");
    L.push("Change each with the owning tool's own command, never by editing its file from here:", "");
    for (const s of settings) L.push(`- ${s.id}: set \`${s.knob.key}\` to \`${s.shown}\` in ${s.knob.file} with ${s.knob.change_with}.`);
    L.push("");
  }
  if (way.writer === "kitctl" && kit.length) {
    L.push(`### ${n++}. kitctl loadouts`, "");
    L.push(`If kitctl is installed, these replace step 2's hand placement: save each loadout to \`~/kits/loadouts/\`${agentPrims.length ? ", each agent primitive to `~/kits/primitives/agents/`" : ""}, run \`kitctl validate\`, then in each repo \`kitctl use gestalt-flow\` plus that repo's context loadout. kitctl writes the native config and the blocks${agentPrims.length ? ", and the subagent workers' files" : ""}.`, "");
    for (const f of kit) L.push(`\`~/kits/loadouts/${f.split("/").pop()}\``, "", fence("yaml", files[f]), "");
    for (const f of agentPrims) {
      const id = f.split("/").pop().slice(0, -5);
      const assets = [["claude.md", `agents/claude/${id}.md`], ["codex.toml", `agents/codex/${id}.toml`]].filter(([a]) => files[`kit/primitives/agents/${id}/${a}`]);
      L.push(`\`~/kits/primitives/agents/${id}.yaml\`${assets.length ? `, with ${assets.map(([a, src]) => `\`~/kits/primitives/agents/${id}/${a}\` (the text of \`${src}\` under Workers)`).join(" and ")}` : ""}`, "", fence("yaml", files[f]), "");
    }
  }

  const workers = Object.keys(files).filter(f => f.startsWith("agents/") || f.startsWith("workers/")).sort();
  if (workers.length) {
    L.push(`### ${n++}. Workers`, "");
    if (kitAgents) L.push("With kitctl, skip the subagent files below: kitctl places them with `gestalt-flow`. Without it, subagent files go in `~/.claude/agents/` (Codex agents in `~/.codex/agents/`). Worker scripts and their prompts go in `~/.gestalt/build/workers/` (make the `.sh` executable). Only on harnesses that run them (Claude Code and Codex for subagents; anything with a shell for headless scripts).", "");
    else L.push("Subagent files go in `~/.claude/agents/` (Codex agents in `~/.codex/agents/`); worker scripts and their prompts in `~/.gestalt/build/workers/` (make the `.sh` executable). Only on harnesses that run them (Claude Code for subagents; anything with a shell for headless scripts).", "");
    for (const f of workers) {
      const target = f.startsWith("agents/claude/") ? `~/.claude/agents/${f.split("/").pop()}` : f.startsWith("agents/codex/") ? `~/.codex/agents/${f.split("/").pop()}` : `~/.gestalt/build/${f}`;
      const lang = f.endsWith(".sh") ? "sh" : f.endsWith(".json") ? "json" : f.endsWith(".toml") ? "toml" : "markdown";
      L.push(`\`${target}\``, "", fence(lang, files[f]), "");
    }
  }

  L.push("## Verify", "");
  L.push(`The setup is done when taste prompt ${pilot ? pilot.i + 1 : 1} passes. The full test, with expected traces and scoring tables:`, "");
  L.push("<details><summary>TASTE-TEST.md</summary>", "", files["TASTE-TEST.md"].replace(/^# .*\n/, ""), "</details>", "");
  return `${L.join("\n")}\n`;
}
